    const score    = scoreItem(j, title, category, brand, discount_pct);

    // categoria_origem = categoria definida na URL/CONFIG ML (round-robin das 5 categorias).
    // categoria_detectada = classificação automática por palavra-chave no título (eletrônicos, moda, etc).
    // "categoria" segue sendo a categoria de ORIGEM, pra não quebrar o round-robin e os limites por categoria no Dedupe.
    const categoriaOrigem = j.categoria || cfg.ml_category_name || category.key;

    out.push({
      json: {
        ...j,
        categoria:           categoriaOrigem,
        categoria_origem:    categoriaOrigem,
        categoria_detectada: category.key,
        categoria_label:     category.label,
        name_key:        category.key,
        marca:           brand?.key ?? null,
        marca_label:     brand?.label ?? null,
        discount_pct_preview: discount_pct,
        score,
        _heuristica: { title_raw: titleRaw, title_norm: title }
      }
    });
  } catch (err) {
    out.push({ json: { _error: true, _error_message: err?.message ?? String(err), _original: it.json ?? null } });
  }
}

return out;

// ===== Helpers =====
function buildPaginatedUrl(baseUrl, page) {
  // Remove fragmento (#...) e espacos: o que vem depois de # nao vai pro servidor
  // e fazia o page=N/_Desde_N cair dentro do fragmento, quebrando a paginacao.
  baseUrl = String(baseUrl).trim().split("#")[0];
  // /lista.mercadolivre.com.br usa offset (_Desde_N), 48 items por página
  if (baseUrl.includes('lista.mercadolivre.com.br')) {
    if (page <= 1) return baseUrl;
    const offset = (page - 1) * 48 + 1;
    const seg = `_Desde_${offset}`;
    // ML tem ordem canonica fixa: ..._CustoFrete_Gratis _Desde_N _DiscountRange_30-100 _NoIndex_True
    // Inserir o _Desde_N FORA dessa ordem faz o ML responder 200 com aviso de redirect
    // no corpo (sem produtos). Entao inserimos logo ANTES do _DiscountRange (ou _NoIndex).
    if (baseUrl.includes('_DiscountRange')) {
      return baseUrl.replace('_DiscountRange', `${seg}_DiscountRange`);
    }
    if (baseUrl.includes('_NoIndex')) {
      return baseUrl.replace('_NoIndex', `${seg}_NoIndex`);
    }
    if (baseUrl.includes('_')) {
      return baseUrl.replace(/_([A-Z])/, `${seg}_$1`);
    }
    return `${baseUrl}${seg}`;
  }

  // /ofertas, /c/, busca normal — paginação via ?page=N
  if (page <= 1) return baseUrl;
  const sep = baseUrl.includes('?') ? '&' : '?';
  return `${baseUrl}${sep}page=${page}`;
}

// ===== Estado do LOOP de tentativas (retry pra atingir o piso de produtos) =====
// Cada vez que o workflow volta aqui (porque não atingiu o piso na tentativa anterior),
// avança um bloco de páginas novo, pra não repetir o que já foi varrido antes.
const staticData = $getWorkflowStaticData('global'); // 'global' = compartilhado entre TODOS os nodes (precisa ser visto pelo 'Acumular Resultados')

// ===== Reset de estado a cada EXECUCAO nova (agendada/manual) =====
// O Static Data sobrevive entre execucoes. Sem zerar, 'tentativa' e 'acumulados'
// vazariam de um dia pro outro, fazendo o pageOffset crescer pra paginas inexistentes.
// So zera quando a execucao mudou; dentro do mesmo run (retry) mantem o acumulado.
const _execId = $execution?.id ?? null;
if (staticData._execId !== _execId) {
  staticData._execId = _execId;
  staticData.tentativa = 0;
  staticData.acumulados = [];
}
const tentativa = Number(staticData.tentativa || 0);
const pagesPerAttempt = Number((($items('CONFIG ML')?.[0]?.json?.ml_queries)
  ? (() => { try {
        const raw = $items('CONFIG ML')[0].json.ml_queries;
        return (typeof raw === 'string' ? JSON.parse(raw) : raw).settings?.pages;
      } catch(e) { return null; } })()
  : null) || 5);
const pageOffset = tentativa * pagesPerAttempt;

// ===== Config =====
// Lê SEMPRE do node CONFIG ML (não do input direto), pois este node também é
// alimentado pelo "IF - Precisa Mais?" nas voltas do loop, cujo input não traz a config.
const cfg = ($items('CONFIG ML')?.[0]?.json) ?? {};

const settings = (() => {
  const s = cfg.ml_queries;
  if (s !== null && typeof s === 'object' && !Array.isArray(s)) return s.settings || s;
  if (typeof s === 'string') {
    try { const p = JSON.parse(s); return p.settings || p; } catch (e) {}
  }
  return {};
})();

const pages = Math.max(1, Number(settings.pages || 5));

const excludeCategories = Array.isArray(settings.exclude_categories)
  ? settings.exclude_categories
  : [];

// ===== Categorias (múltiplas URLs) =====
// ml_categories é um array de objetos { nome, url }, configurado no node CONFIG ML.
// Mantém compatibilidade: se não houver ml_categories, cai de volta no ml_base_url antigo (1 categoria só).
let categories = [];
try {
  const raw = cfg.ml_categories;
  if (Array.isArray(raw)) {
    categories = raw;
  } else if (typeof raw === 'string' && raw.trim()) {
    categories = JSON.parse(raw);
  }
} catch (e) {
  categories = [];
}

if (!Array.isArray(categories) || categories.length === 0) {
  // Fallback ROBUSTO: nichos embutidos no proprio node.
  // Garante o round-robin mesmo se o campo ml_categories do CONFIG vier
  // vazio ou quebrado (era isso que derrubava tudo pro feed generico 'casa').
  categories = [
    { nome: "airfryer", url: "https://lista.mercadolivre.com.br/air-fryer_CustoFrete_Gratis_DiscountRange_30-100_NoIndex_True" },
    { nome: "cama", url: "https://lista.mercadolivre.com.br/jogo-de-cama-casal_CustoFrete_Gratis_DiscountRange_30-100_NoIndex_True" },
    { nome: "organizador", url: "https://lista.mercadolivre.com.br/organizador-de-cozinha_CustoFrete_Gratis_DiscountRange_30-100_NoIndex_True" },
    { nome: "vestido", url: "https://lista.mercadolivre.com.br/vestido-feminino_CustoFrete_Gratis_DiscountRange_30-100_NoIndex_True" },
    { nome: "conjunto", url: "https://lista.mercadolivre.com.br/conjunto-feminino_CustoFrete_Gratis_DiscountRange_30-100_NoIndex_True" },
    { nome: "bolsa", url: "https://lista.mercadolivre.com.br/bolsa-feminina_CustoFrete_Gratis_DiscountRange_30-100_NoIndex_True" },
    { nome: "oculos", url: "https://lista.mercadolivre.com.br/oculos-de-sol-feminino_CustoFrete_Gratis_DiscountRange_30-100_NoIndex_True" },
    { nome: "perfume", url: "https://lista.mercadolivre.com.br/perfume-importado_CustoFrete_Gratis_DiscountRange_30-100_NoIndex_True" },
    { nome: "creme", url: "https://lista.mercadolivre.com.br/creme-hidratante-corporal_CustoFrete_Gratis_DiscountRange_30-100_NoIndex_True" },
    { nome: "legging", url: "https://lista.mercadolivre.com.br/legging-fitness_CustoFrete_Gratis_DiscountRange_30-100_NoIndex_True" },
    { nome: "fitness", url: "https://lista.mercadolivre.com.br/conjunto-fitness-feminino_CustoFrete_Gratis_DiscountRange_30-100_NoIndex_True" }
  ];
}

// Filtra categorias sem URL válida (ex: placeholders não preenchidos)
categories = categories.filter(c => c && c.url && !/^COLE_AQUI/i.test(String(c.url).trim()));

// ===== Geração dos links em ROUND-ROBIN por categoria =====
// Ordem de saída: cat1_p1, cat2_p1, cat3_p1, ..., catN_p1, cat1_p2, cat2_p2, ...
// Assim o scraping já visita as categorias intercaladas, página por página.
const out = [];

try {
  for (let page = 1; page <= pages; page++) {
    const pageReal = page + pageOffset; // avança o bloco de páginas a cada tentativa do loop
    for (const cat of categories) {
      const baseUrl = String(cat.url).trim();
      const categoryName = String(cat.nome || 'categoria').trim();
      const link = buildPaginatedUrl(baseUrl, pageReal);

      out.push({
        json: {
          marketplace: 'mercadolivre',
          name: `${categoryName}_p${pageReal}`,
          categoria: categoryName,
          page: pageReal,
          tentativa,
          link,
          min_discount:        Number(settings.min_discount ?? 10),
          min_rating:          Number(settings.min_rating   ?? 4.0),
          free_shipping:       settings.free_shipping ?? true,
          sort:                settings.sort || 'discount_desc',
          exclude_categories:  excludeCategories,
          ml_affiliate_endpoint: cfg.ml_affiliate_endpoint,
          ml_affiliate_tag:      cfg.ml_affiliate_tag,
          ml_csrf_token:         cfg.ml_csrf_token,
          ml_cookie:             cfg.ml_cookie,
        },
      });
    }
  }
} catch (err) {
  // Não derruba o workflow se algo bizarro acontecer aqui
  out.push({
    json: {
      _error: true,
      _error_message: err?.message ?? String(err),
      _categories: categories,
    },
  });
}

return out;

// pega tudo que já existe na Data Table
const existingRows = $('Get Existing IDs').all();

// cria Set com os link_compra já salvos
const existingLinks = new Set(
