// ===== Extrai produtos de TODAS as paginas (1 item de entrada = 1 pagina) =====
// ANTES: parseava so a 1a pagina -> com round-robin de varios nichos vinha "so o 1o".
// AGORA: percorre $input.all(), parseia CADA pagina e marca a categoria de origem por produto.

function ehHtml(v){ return typeof v==='string' && (v.includes('_n.ctx.s.q')||v.includes('polycard')); }
function buscaEm(o,p=0){
  if(!o||p>2) return null;
  for(const k of Object.keys(o)){
    const v=o[k];
    if(ehHtml(v)) return v;
    if(v&&typeof v==='object'){ const r=buscaEm(v,p+1); if(r) return r; }
  }
  return null;
}
function slice(str,start){
  const open=str[start], close=open==='{'?'}':']';
  let d=0,inStr=false,esc=false;
  for(let i=start;i<str.length;i++){
    const c=str[i];
    if(inStr){ if(esc)esc=false; else if(c==='\\')esc=true; else if(c==='"')inStr=false; }
    else{ if(c==='"')inStr=true; else if(c===open)d++; else if(c===close){ d--; if(!d) return str.slice(start,i+1); } }
  }
  return null;
}
function brl(v){
  const n=Number(v); if(!isFinite(n)) return String(v);
  const [i,d]=n.toFixed(2).split('.');
  return i.replace(/\B(?=(\d{3})+(?!\d))/g,'.')+','+d;
}

const MIN_DESCONTO = 30; // % minimo de desconto exigido

// Parseia UMA pagina (string html) -> {nomes,imgs,precos,links,vendas,avaliacoes} ou null
function parsePagina(html){
  if(!html) return null;
  const m=html.match(/_n\.ctx\.s\.q\("0:((?:\\.|[^"\\])*)"\)/);
  if(!m) return null;
  const raw=JSON.parse('"'+m[1]+'"');

  let results=[];
  for(const mm of raw.matchAll(/"results":\s*\[/g)){
    const br=raw.indexOf('[',mm.index);
    const arr=slice(raw,br);
    if(arr && arr.includes('"polycard":{')){ results=JSON.parse(arr); break; }
  }

  let ctx={};
  const ci=raw.indexOf('"polycard_context"');
  if(ci>=0){ const ob=raw.indexOf('{',ci); const o=slice(raw,ob); if(o) ctx=JSON.parse(o); }

  const prefix=ctx.url_prefix??'https://';
  const picTpl=ctx.picture_template??'https://http2.mlstatic.com/D_{square}_NP{2x}_{id}-{size}.webp';
  const getComp=(comps,t)=>(comps||[]).find(c=>c.type===t);
  function montaImg(p){
    const pic=p.pictures?.pictures?.[0]?.id; if(!pic) return '';
    const square=p.pictures?.square??ctx.picture_square_default??'Q';
    const size=ctx.picture_size_default??'T';
    return picTpl.replace('{square}',square).replace('{2x}','').replace('{id}',pic)
                .replace('{size}',size).replace('{sanitized_title}',p.pictures?.sanitized_title??'');
  }

  const nomes=[],imgs=[],precos=[],links=[],vendas=[],avaliacoes=[];
  for(const r of results){
    const p=r.polycard;
    if(!p) continue;
    if(p.metadata?.is_pad==='true') continue;       // remova p/ incluir patrocinados
    const comps=p.components;
    const title=getComp(comps,'title')?.title?.text??'';
    const price=getComp(comps,'price')?.price??{};
    const novo=price.current_price?.value, velho=price.previous_price?.value;
    if(!velho || !novo) continue;
    if(Math.round((1 - novo/velho) * 100) < MIN_DESCONTO) continue;
    let url=p.metadata?.url??''; if(url&&!url.startsWith('http')) url=prefix+url;
    nomes.push(title); imgs.push(montaImg(p)); links.push(url);
    precos.push(`R$ ${brl(velho)}R$ ${brl(novo)}`);
    const sold=getComp(comps,'review_compacted')?.review_compacted?.values?.find(v=>v.key==='label2')?.label?.text??'';
    vendas.push(sold);
    const rate=getComp(comps,'review_compacted')?.review_compacted?.values?.find(v=>v.key==='label1')?.label?.text??'';
    avaliacoes.push(rate);
  }
  return {nomes,imgs,precos,links,vendas,avaliacoes};
}

// ----- percorre TODAS as paginas vindas do round-robin -----
const out=[];
for(const it of $input.all()){
  const j = it.json || {};
  const html = buscaEm(j) || buscaEm(it.binary);
  const r = parsePagina(html);
  if(!r || r.nomes.length===0) continue;             // pagina sem produtos -> ignora
  const cat = j.categoria || j.categoria_origem || '';
  const cats = new Array(r.nomes.length).fill(cat);  // categoria por produto desta pagina
  out.push({json:{
    'Nomes Produtos':r.nomes,'Imagem Produtos (src)':r.imgs,'preco':r.precos,'link_compra':r.links,
    'Imagem Produtos (data-src)':r.imgs,'Imagem Produtos (srcset)':r.imgs,'Imagem Produtos (data-srcset)':r.imgs,
    'vendas_text':r.vendas,'vendas_text_alt':r.vendas,'rating_text':r.avaliacoes,
    'categoria':cats
  }});
}

if(out.length===0){
  return [{json:{
    'Nomes Produtos':[],'Imagem Produtos (src)':[],'preco':[],'link_compra':[],
    'Imagem Produtos (data-src)':[],'Imagem Produtos (srcset)':[],'Imagem Produtos (data-srcset)':[],
    'vendas_text':[],'vendas_text_alt':[],'rating_text':[],'categoria':[],
    _erro:'nenhuma pagina com produtos'
  }}];
}
return out;
